      "milestone_id": "craft_dark_oak_sign",
      "description": "Uses inventory_has because crafting a dark_oak_sign (from 6 dark_oak_planks + 1 stick at a crafting table) results in dark_oak_sign appearing in the player's inventory. The player starts with 0 dark_oak_sign, so this cannot be a false positive at initialization.",
      "rules": [
        {
